// Monitor STDIN for readiness (POLLIN)
struct pollfd fds[1];
fds[0].fd = STDIN_FILENO;
fds[0].events = POLLIN;

int timeout_ms = 5000; // 5 seconds

// Block until ready or timeout
int ret = poll(fds, 1, timeout_ms);

if (ret < 0) {
    /* Handle Error (e.g., EINTR) */
} else if (ret == 0) {
    /* Timeout occurred */
} else {
    // Event occurred on one or more FDs
    if (fds[0].revents & POLLIN) {
        /* STDIN is ready to read */
    }
    if (fds[0].revents & POLLERR) {
        /* File descriptor error status */
    }
}
